// Ported from Limbophobia src/content/furniture/zw_home.ts (same author): its texture painters only; the geometry and game code stay there.
// Generated by the material library's extractor and then kept by hand. Paints at 32 px per metre (src/gfx/mat/atlas.ts).
import { addTextureModule } from '../../../textures/index';
import { atlas } from '../../../atlas';
import { type PixelCanvas, mixHex, bayer, ph } from '../../../pixel';
import { atlasRepaint, blitPortrait } from '../../entities/portrait';
import { crtGlass } from './a_lib';

/** a family portrait: k people, faces smeared to nothing */
function portrait(pc: PixelCanvas, v: number) {
  pc.wrap = false;
  const W = pc.w, H = pc.h;
  const bg = [0x7a8aa0, 0x9a8a6a, 0x6a7a6a, 0x8a7a8a][v % 4];
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) pc.set(x, y, mixHex(bg, 0x2a2a30, (y / H) * 0.35 + (bayer(x, y) < 0.15 ? 0.05 : 0)));
  const n = [4, 3, 5, 2][v % 4];
  // the family: renders of HumanRigs (entities/portrait.ts), never drawn; then each face smeared sideways like a thumb dragged through wet paint
  const later = atlasRepaint('zw_portrait_' + v);
  const people: { cx: number; top: number; hw: number; seed: number; jump?: boolean }[] = [];
  for (let i = 0; i < n; i++) {
    const cx = Math.round(((i + 0.5) / n) * W), small = i >= n - 1 && n > 2;
    people.push({ cx, top: Math.round(small ? H * 0.42 : H * 0.14), hw: Math.max(3, Math.floor(W / n / 2) + 1), seed: 360 + ((v * 5 + i) % 9) });
  }
  // the one in the jumpsuit (the newest copy of the family has an extra member)
  if (v === 3) people.push({ cx: W - 5, top: Math.round(H * 0.18), hw: 4, seed: 4471, jump: true });
  for (const q of people) blitPortrait(pc, q.cx - q.hw, q.top, q.hw * 2 + 1, H - q.top, { seed: q.seed, outfit: q.jump ? 'jumpsuit' : 'civilian', light: 'studio', frame: 'chest', bg: null }, bg, later);
  people.forEach((q, i) => {
    if (q.jump) return;
    const fy = q.top + Math.round((H - q.top) * 0.16), fh = Math.max(3, Math.round((H - q.top) * 0.2));
    for (let y = fy; y < fy + fh; y++) for (let x = q.cx - q.hw + 1; x <= q.cx + q.hw + 2; x++) {
      if (ph(x, y, 8501 + i) < 0.75) pc.blend(x, y, mixHex(pc.get(x - 2, y), bg, 0.35), 0.85);
    }
  });
}
addTextureModule(() => {
  const A = atlas();
  for (let v = 0; v < 4; v++) A.add('zw_portrait_' + v, 28, 22, (pc) => portrait(pc, v));
  A.add('zw_static', 16, 12, (pc) => {
    pc.wrap = false;
    pc.each((x, y) => { const n = ph(x, y, 8511); pc.set(x, y, n < 0.3 ? 0x2a2a30 : n < 0.6 ? 0x8a8a94 : n < 0.85 ? 0xc8c8d0 : 0xf0f0f4); });
    for (let x = 0; x < 16; x++) pc.blend(x, 5, 0xffffff, 0.5);
    crtGlass(pc, 0, 0, 16, 12, 0x0a0a0c, 0.5);
  });
  A.add('zw_plate_food', 16, 16, (pc) => {
    pc.wrap = false; pc.clear();
    pc.circle(7.5, 7.5, 7.5, 0xf4f0e8); pc.circle(7.5, 7.5, 5.8, 0xe8e2d4);
    pc.ellipse(6, 6, 3, 2, 0x8a4a2a); pc.ellipse(9.5, 9, 2.4, 2, 0x5a8a3a); pc.ellipse(9, 5.5, 2, 1.6, 0xe8d090);
    pc.set(5, 5, 0xb87a4a); pc.set(10, 8, 0x7aaa5a);
  });
  A.add('zw_plate_empty', 16, 16, (pc) => {
    pc.wrap = false; pc.clear();
    pc.circle(7.5, 7.5, 7.5, 0xf4f0e8); pc.circle(7.5, 7.5, 5.8, 0xeae6da);
    for (let a = 0; a < 6.28; a += 0.4) pc.set(Math.round(7.5 + Math.cos(a) * 6.6), Math.round(7.5 + Math.sin(a) * 6.6), 0x6a8ab0);
  });
  A.add('zw_tablecloth', 32, 32, (pc) => {
    pc.each((x, y) => pc.set(x, y, ((x >> 2) + (y >> 2)) & 1 ? 0xe8e0d0 : (((x >> 2) & 1) ? 0xc87a7a : 0xe8e0d0)));
    for (let x = 0; x < 32; x += 4) for (let y = 0; y < 32; y++) if (ph(x, y, 8521) < 0.1) pc.set(x, y, 0xd8d0c0);
  });
});
